//! `url_parser` — a faithful port of the C++ URL parsing library.
//!
//! Parsing is deliberately *lexical* rather than standards-compliant: the C++
//! original recognises components purely by delimiter position and performs no
//! grammar validation on the scheme or host. The submodules mirror that split:
//!
//! * [`ascii`]   — C-locale character helpers (`tolower`, `isspace`).
//! * [`numeric`] — an emulation of `std::stoi` used for port conversion.
//! * [`split`]   — the delimiter scans that carve a URL into components.
//! * [`url`]     — the [`URL`] type assembled from the pieces above.

pub mod ascii;
pub mod numeric;
pub mod split;
pub mod url;

pub use url::URL;

//! The [`URL`] value type: parses once on construction, then hands out
//! components through accessors mirroring the C++ header.

use super::ascii;
use super::numeric::{self, NO_PORT};
use super::split;

/// A parsed URL.
///
/// Construction never fails; a string that carries no usable location simply
/// reports [`URL::is_valid`] as `false`.
///
/// ```
/// use url_parser::URL;
///
/// let url = URL::new("https://user:pass@example.com:8080/a/b?x=1#top");
/// assert_eq!(url.scheme(), "https");
/// assert_eq!(url.authority(), "user:pass@example.com:8080");
/// assert_eq!(url.port(), 8080);
/// assert_eq!(url.path(), "/a/b");
/// assert_eq!(url.query(), "x=1");
/// assert_eq!(url.fragment(), "top");
/// assert!(url.is_valid());
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    authority: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    /// Parses `input`, mirroring the C++ `url_parser::URL` constructor.
    ///
    /// The delimiter order is fragment, then query, then scheme, then the
    /// authority/path split — see [`split`](super::split) for why that is
    /// observable.
    pub fn new(input: &str) -> Self {
        let (before_fragment, fragment) = split::split_fragment(input);
        let (before_query, query) = split::split_query(before_fragment);

        let mut url = URL {
            scheme: String::new(),
            authority: String::new(),
            host: String::new(),
            port: NO_PORT,
            path: String::new(),
            query: query.to_string(),
            fragment: fragment.to_string(),
        };

        match split::split_scheme(before_query) {
            // No `"://"`: everything left over is the path, and there is no
            // authority to speak of.
            None => url.path = before_query.to_string(),
            Some((scheme, after_scheme)) => {
                url.scheme = ascii::to_lower(scheme);

                let (raw_authority, path) = split::split_authority_and_path(after_scheme);
                url.path = path.to_string();

                let (userinfo, host_port) = split::split_userinfo(raw_authority);
                let (host, port_text) = split::split_host_port(host_port);
                url.host = host.to_string();
                if let Some(text) = port_text {
                    url.port = numeric::parse_port(text);
                }
                url.authority = rebuild_authority(userinfo, host, url.port);
            }
        }

        url
    }

    /// The lower-cased scheme, without the `"://"`; empty when absent.
    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    /// The authority as re-serialised from userinfo, host and port.
    ///
    /// This is *not* a slice of the input: an unusable port is dropped along
    /// with its colon, and a usable one is re-rendered in canonical decimal, so
    /// `"h:065"` comes back as `"h:65"` and `"h:abc"` as `"h"`.
    pub fn authority(&self) -> &str {
        &self.authority
    }

    /// The port, or `-1` when none was written or the written one was unusable.
    pub fn port(&self) -> i32 {
        self.port
    }

    /// The path, including its leading `'/'`; empty when absent.
    pub fn path(&self) -> &str {
        &self.path
    }

    /// The query, without the leading `'?'`; empty when absent.
    pub fn query(&self) -> &str {
        &self.query
    }

    /// The fragment, without the leading `'#'`; empty when absent.
    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    /// Whether the URL names something: a non-empty host or a non-empty path.
    ///
    /// A scheme, query or fragment on its own is not enough, so `"http://"`,
    /// `"http://?q"` and `"http://:80"` are all invalid while `"/"` is valid.
    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

/// Re-renders the authority from its parsed pieces.
///
/// The `'@'` is emitted only for a non-empty userinfo, which is why `"@h:80"`
/// canonicalises to `"h:80"` while `"h:80@"` keeps its trailing `'@'`.
fn rebuild_authority(userinfo: &str, host: &str, port: i32) -> String {
    let mut authority = String::new();
    if !userinfo.is_empty() {
        authority.push_str(userinfo);
        authority.push('@');
    }
    authority.push_str(host);
    if port != NO_PORT {
        authority.push(':');
        authority.push_str(&port.to_string());
    }
    authority
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Compact spelling of an expected parse, matching the seven printed lines.
    fn parsed(input: &str) -> (String, String, i32, String, String, String, bool) {
        let u = URL::new(input);
        (
            u.scheme().to_string(),
            u.authority().to_string(),
            u.port(),
            u.path().to_string(),
            u.query().to_string(),
            u.fragment().to_string(),
            u.is_valid(),
        )
    }

    #[test]
    fn parses_a_full_url() {
        assert_eq!(
            parsed("https://user:pass@host.com:443/a/b?x=y&z=2#top"),
            (
                "https".into(),
                "user:pass@host.com:443".into(),
                443,
                "/a/b".into(),
                "x=y&z=2".into(),
                "top".into(),
                true
            )
        );
    }

    #[test]
    fn scheme_is_lowercased_but_nothing_else_is() {
        assert_eq!(
            parsed("HTTP://Example.COM/Path"),
            (
                "http".into(),
                "Example.COM".into(),
                -1,
                "/Path".into(),
                String::new(),
                String::new(),
                true
            )
        );
    }

    #[test]
    fn missing_separator_makes_the_whole_string_a_path() {
        assert_eq!(URL::new("http:example.com").scheme(), "");
        assert_eq!(URL::new("http:example.com").path(), "http:example.com");
        assert_eq!(URL::new("example.com").path(), "example.com");
        assert_eq!(URL::new("//example.com/p").path(), "//example.com/p");
    }

    #[test]
    fn fragment_is_removed_before_the_scheme_is_sought() {
        assert_eq!(URL::new("#f=://x").scheme(), "");
        assert_eq!(URL::new("#f=://x").fragment(), "f=://x");
        assert_eq!(URL::new("?q=://x").query(), "q=://x");
        assert_eq!(URL::new("/a://b").scheme(), "/a");
    }

    #[test]
    fn unusable_ports_drop_their_colon() {
        assert_eq!(parsed("http://h:abc/p").1, "h");
        assert_eq!(parsed("http://h:65536/p").1, "h");
        assert_eq!(parsed("http://a:b:c/p").1, "a");
        assert_eq!(parsed("http://h:065/p").1, "h:65");
        assert_eq!(parsed("http://h:+80/p").1, "h:80");
    }

    #[test]
    fn validity_tracks_host_and_path_only() {
        assert!(!URL::new("").is_valid());
        assert!(!URL::new("http://").is_valid());
        assert!(!URL::new("http://?q").is_valid());
        assert!(!URL::new("http://:80").is_valid());
        assert!(!URL::new("http://u@").is_valid());
        assert!(URL::new("/").is_valid());
        assert!(URL::new("http:// ").is_valid());
        assert!(URL::new("http://h:80@/p").is_valid());
    }
}

//! The delimiter scans that carve a URL string into its components.
//!
//! Every function here is a pure lexical split returning borrowed slices, in
//! the same order the C++ constructor applies them. That order is observable:
//! because the fragment is removed before the scheme is looked for, a `"://"`
//! sitting inside a fragment or query never produces a scheme.
//!
//! All delimiters are ASCII, so the returned byte offsets always land on UTF-8
//! character boundaries.

/// Splits the fragment at the **first** `'#'`, returning `(remainder, fragment)`.
///
/// Later `'#'` and `'?'` characters stay inside the fragment.
pub fn split_fragment(input: &str) -> (&str, &str) {
    match input.find('#') {
        Some(at) => (&input[..at], &input[at + 1..]),
        None => (input, ""),
    }
}

/// Splits the query at the **first** `'?'`, returning `(remainder, query)`.
///
/// Runs after [`split_fragment`], so it only ever sees the pre-fragment text.
pub fn split_query(input: &str) -> (&str, &str) {
    match input.find('?') {
        Some(at) => (&input[..at], &input[at + 1..]),
        None => (input, ""),
    }
}

/// Splits on the first `"://"`, returning `(raw_scheme, remainder)`.
///
/// Returns `None` when the separator is absent, which is what makes a bare
/// `"http:example.com"` parse as a path rather than a scheme. Note that no
/// grammar check is applied to the scheme text: `"1http"`, `"ht tp"` and `"/a"`
/// are all accepted verbatim, exactly as the C++ version accepts them.
pub fn split_scheme(input: &str) -> Option<(&str, &str)> {
    input
        .find("://")
        .map(|at| (&input[..at], &input[at + 3..]))
}

/// Splits the post-`"://"` text into `(raw_authority, path)` at the first `'/'`.
///
/// The `'/'` itself belongs to the path, and an absent `'/'` yields an empty
/// path rather than an empty authority.
pub fn split_authority_and_path(input: &str) -> (&str, &str) {
    match input.find('/') {
        Some(at) => (&input[..at], &input[at..]),
        None => (input, ""),
    }
}

/// Splits the raw authority at the **first** `'@'`, returning `(userinfo, host_port)`.
///
/// First — not last — which is why `"a@b:80@c:90"` has userinfo `"a"` and host
/// port text `"b:80@c:90"`, giving port `80`.
pub fn split_userinfo(authority: &str) -> (&str, &str) {
    match authority.find('@') {
        Some(at) => (&authority[..at], &authority[at + 1..]),
        None => ("", authority),
    }
}

/// Splits the host/port text at the **first** `':'`, returning
/// `(host, port_text)`.
///
/// `port_text` is `None` when there is no colon at all, distinguishing "no port
/// was written" from "a port was written but did not convert".
pub fn split_host_port(host_port: &str) -> (&str, Option<&str>) {
    match host_port.find(':') {
        Some(at) => (&host_port[..at], Some(&host_port[at + 1..])),
        None => (host_port, None),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fragment_and_query_take_the_first_delimiter() {
        assert_eq!(split_fragment("a#b#c"), ("a", "b#c"));
        assert_eq!(split_fragment("a?b#c"), ("a?b", "c"));
        assert_eq!(split_query("a?b?c"), ("a", "b?c"));
        assert_eq!(split_query("no-query"), ("no-query", ""));
    }

    #[test]
    fn scheme_requires_the_full_separator() {
        assert_eq!(split_scheme("http://h"), Some(("http", "h")));
        assert_eq!(split_scheme("/a://b"), Some(("/a", "b")));
        assert_eq!(split_scheme("http:/h"), None);
        assert_eq!(split_scheme("http:h"), None);
    }

    #[test]
    fn authority_stops_at_the_first_slash() {
        assert_eq!(split_authority_and_path("h/p/q"), ("h", "/p/q"));
        assert_eq!(split_authority_and_path("h"), ("h", ""));
        assert_eq!(split_authority_and_path("/p"), ("", "/p"));
    }

    #[test]
    fn userinfo_and_port_use_first_delimiters() {
        assert_eq!(split_userinfo("a@b:80@c:90"), ("a", "b:80@c:90"));
        assert_eq!(split_userinfo("h:80@"), ("h:80", ""));
        assert_eq!(split_userinfo("h:80"), ("", "h:80"));
        assert_eq!(split_host_port("a:b:c"), ("a", Some("b:c")));
        assert_eq!(split_host_port("h"), ("h", None));
        assert_eq!(split_host_port("h:"), ("h", Some("")));
    }
}
//! Emulation of `std::stoi` and the port-range check layered on top of it.
//!
//! `std::stoi(s)` delegates to `strtol` with base 10 and then narrows to `int`,
//! which gives it three behaviours a naive `str::parse::<i32>()` does not have:
//!
//! * leading `"C"`-locale whitespace and a single optional sign are accepted;
//! * conversion stops at the first non-digit instead of failing, so `"80abc"`,
//!   `"80.5"` and `"0x50"` yield `80`, `80` and `0`;
//! * a missing digit sequence throws `invalid_argument`, and a value outside
//!   `int` range throws `out_of_range` — both surface here as `None`.

use super::ascii;

/// Widest magnitude we keep accumulating before latching the overflow flag.
///
/// Anything past this is already outside `int` range, so the exact value no
/// longer matters — we only need to keep consuming digits without wrapping the
/// `i64` accumulator.
const OVERFLOW_GUARD: i64 = 1 << 32;

/// Ports the C++ side accepts; anything else collapses to [`NO_PORT`].
const MAX_PORT: i32 = 65535;

/// Sentinel the C++ `port()` accessor returns when no usable port was found.
pub const NO_PORT: i32 = -1;

/// Emulates `std::stoi(s)`, returning `None` where the C++ call would throw.
pub fn stoi(s: &str) -> Option<i32> {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && ascii::is_space(bytes[i]) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(&b'-') => {
            i += 1;
            true
        }
        Some(&b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let first_digit = i;
    let mut magnitude: i64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !overflowed {
            magnitude = magnitude * 10 + i64::from(bytes[i] - b'0');
            overflowed = magnitude > OVERFLOW_GUARD;
        }
        i += 1;
    }

    // No digits at all: `std::stoi` throws `invalid_argument`.
    if i == first_digit {
        return None;
    }
    // Past `int` range: `std::stoi` throws `out_of_range`.
    if overflowed {
        return None;
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        return None;
    }
    Some(value as i32)
}

/// Converts the text following the host's `':'` into a port number.
///
/// Values that fail conversion or fall outside `0..=65535` are reported as
/// [`NO_PORT`], which also suppresses the `":port"` suffix in the rebuilt
/// authority.
pub fn parse_port(text: &str) -> i32 {
    match stoi(text) {
        Some(value) if (0..=MAX_PORT).contains(&value) => value,
        _ => NO_PORT,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stoi_matches_strtol_prefix_semantics() {
        assert_eq!(stoi("80abc"), Some(80));
        assert_eq!(stoi("80.5"), Some(80));
        assert_eq!(stoi("0x50"), Some(0));
        assert_eq!(stoi("8 0"), Some(8));
        assert_eq!(stoi(" \t+80"), Some(80));
        assert_eq!(stoi("065"), Some(65));
        assert_eq!(stoi("-0"), Some(0));
        assert_eq!(stoi("-2147483648"), Some(i32::MIN));
    }

    #[test]
    fn stoi_reports_throwing_cases_as_none() {
        assert_eq!(stoi(""), None);
        assert_eq!(stoi(" "), None);
        assert_eq!(stoi("abc"), None);
        assert_eq!(stoi("--80"), None);
        assert_eq!(stoi("2147483648"), None);
        assert_eq!(stoi("99999999999999"), None);
    }

    #[test]
    fn parse_port_clamps_to_valid_range() {
        assert_eq!(parse_port("0"), 0);
        assert_eq!(parse_port("65535"), 65535);
        assert_eq!(parse_port("65536"), NO_PORT);
        assert_eq!(parse_port("-80"), NO_PORT);
        assert_eq!(parse_port("abc"), NO_PORT);
    }
}
//! C-locale character classification, matching `<cctype>` under the default
//! `"C"` locale that the C++ original runs in.
//!
//! Only ASCII bytes are affected; every other byte is passed through unchanged,
//! so multi-byte UTF-8 sequences survive intact.

/// Equivalent of `std::isspace` in the `"C"` locale.
///
/// This is the set of bytes `std::strtol` (and therefore `std::stoi`) skips
/// before looking for an optional sign.
pub fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Equivalent of applying `std::tolower` to every byte of a string.
pub fn to_lower(s: &str) -> String {
    s.to_ascii_lowercase()
}

